const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Inner Niger Delta (Mali)
  const innerNigerDelta = ee.Geometry.Point([4.0, 14.5]).buffer(50000);

  // 2. Define time periods
  const may2022Start = '2022-05-01';
  const may2022End = '2022-05-31';
  const nov2022Start = '2022-11-01';
  const nov2022End = '2022-11-30';

  // 3. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // 4. Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 5. Get Sentinel-2 data for May 2022
  let mayCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(may2022Start, may2022End)
    .filterBounds(innerNigerDelta)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2clouds)
    .map(addNDVI);

  const maySize = mayCol.size().getInfo();
  console.log(`May 2022 Images: ${maySize}`);

  if (maySize === 0) {
    console.log('No Sentinel-2 data for May 2022, trying Landsat 8...');
    mayCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(may2022Start, may2022End)
      .filterBounds(innerNigerDelta)
      .map(function(image) {
        const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
        return image.addBands(ndvi);
      });

    const mayLandsatSize = mayCol.size().getInfo();
    console.log(`May 2022 Landsat Images: ${mayLandsatSize}`);

    if (mayLandsatSize === 0) {
      console.log('No data available for May 2022.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 6. Get Sentinel-2 data for November 2022
  let novCol = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(nov2022Start, nov2022End)
    .filterBounds(innerNigerDelta)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2clouds)
    .map(addNDVI);

  const novSize = novCol.size().getInfo();
  console.log(`November 2022 Images: ${novSize}`);

  if (novSize === 0) {
    console.log('No Sentinel-2 data for November 2022, trying Landsat 8...');
    novCol = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(nov2022Start, nov2022End)
      .filterBounds(innerNigerDelta)
      .map(function(image) {
        const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
        return image.addBands(ndvi);
      });

    const novLandsatSize = novCol.size().getInfo();
    console.log(`November 2022 Landsat Images: ${novLandsatSize}`);

    if (novLandsatSize === 0) {
      console.log('No data available for November 2022.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 7. Calculate mean NDVI for both periods
  const mayNDVI = mayCol.select('NDVI').median();
  const novNDVI = novCol.select('NDVI').median();

  // 8. Reduce to get mean values with pixel count
  const mayStats = mayNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: innerNigerDelta,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const novStats = novNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: innerNigerDelta,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mayMean = mayStats['NDVI_mean'];
  const mayCount = mayStats['NDVI_count'];
  const novMean = novStats['NDVI_mean'];
  const novCount = novStats['NDVI_count'];

  console.log(`May 2022: NDVI=${mayMean}, Pixels=${mayCount}`);
  console.log(`Nov 2022: NDVI=${novMean}, Pixels=${novCount}`);

  // 9. Validation checks
  if (mayCount === 0 || novCount === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mayMean === null || mayMean === undefined || novMean === null || novMean === undefined) {
    console.log('Calculation failed (null/undefined result).');
    console.log('<answer>C3</answer>');
    return;
  }

  if (mayMean < -1 || mayMean > 1 || novMean < -1 || novMean > 1) {
    console.log('Invalid NDVI values (out of range).');
    console.log('<answer>C3</answer>');
    return;
  }

  // 10. Final comparison
  console.log(`Vegetation change: ${((novMean - mayMean) * 100).toFixed(2)}%`);

  if (novMean > mayMean) {
    console.log('Vegetation coverage increased in November 2022.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Vegetation coverage did not increase in November 2022.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
